import 'dart:convert';import 'dart:io';import 'package:path_provider/path_provider.dart';import 'package:shared_preferences/shared_preferences.dart';import '../models/vault_item.dart';
class VaultStore {
 static Future<List<VaultItem>> items() async {final p=await SharedPreferences.getInstance();return (p.getStringList('pv_items')??[]).map((s)=>VaultItem.fromJson(jsonDecode(s))).toList();}
 static Future<void> addFile(File f,{String method='Imported'}) async {final p=await SharedPreferences.getInstance();final list=await items();final d=await getApplicationDocumentsDirectory();final vault=Directory('${d.path}/vault');await vault.create(recursive:true);final copy=File('${vault.path}/${DateTime.now().microsecondsSinceEpoch}_${f.uri.pathSegments.last}');await f.copy(copy.path);list.insert(0,VaultItem(id:DateTime.now().microsecondsSinceEpoch.toString(),name:f.uri.pathSegments.last,path:copy.path,type:_type(f.path),method:method,bytes:await copy.length(),created:DateTime.now()));await p.setStringList('pv_items',list.map((e)=>jsonEncode(e.toJson())).toList());}
 static String _type(String path){final ext=path.split('.').last.toLowerCase();if(['png','jpg','jpeg','webp','gif'].contains(ext))return 'Image';if(['pdf','doc','docx','txt'].contains(ext))return 'Document';if(['mp4','mov','mkv'].contains(ext))return 'Video';return 'File';}
 static Future<void> remove(VaultItem i) async {final p=await SharedPreferences.getInstance();final list=await items();list.removeWhere((e)=>e.id==i.id);await p.setStringList('pv_items',list.map((e)=>jsonEncode(e.toJson())).toList());try{await File(i.path).delete();}catch(_){} }
}
